const existingPhotos = new Map(partCatalog.map(part => [part.id, part.photo]));
const applications = {
  vanos:'Equipped BMW petrol engines, including the B38 family documented in BMW technical training. The version and drive hardware vary.',
  valvetronic:'Equipped BMW petrol engines, including the B38 family. It is not present on every BMW petrol engine.',
  'spark-plug':'BMW spark-ignition petrol engines, including the combustion engine in petrol plug-in hybrids. Not diesel engines or battery-electric drive units.',
  'ignition-coil':'BMW spark-ignition petrol engines, including petrol plug-in hybrids. Diesel engines do not use spark-ignition coils.',
  'glow-plug':'BMW diesel engines equipped with a controlled glow system. Not a substitute for petrol spark plugs.',
  'diesel-particulate-filter':'Equipped BMW diesel models, according to engine, production date and market. Not a petrol exhaust filter.',
  'petrol-particulate-filter':'Equipped BMW petrol models, according to engine, production date and market. Not all petrol generations have one.',
  'scr-catalyst':'BMW diesel models fitted with SCR after-treatment; verify the specific engine and market.',
  'adblue-tank':'BMW diesel models fitted with a urea-dosing SCR system; not every BMW diesel uses this equipment.',
  'm-differential':'Equipped BMW M models; the F10 M5 manufacturer description is one documented example. Other axle differentials work differently.',
  'carbon-ceramic-brakes':'BMW M models equipped with the specific M carbon-ceramic brake option. An M Sport appearance package does not establish this fitment.',
  'm-steering-wheel':'BMW M cars and equipped BMW M Sport or other specified variants. The wheel, switches and restraint hardware must match the exact car.',
  'transfer-case':'Longitudinal-engine BMW xDrive applications using a transfer case. Transverse-engine and electric xDrive arrangements can use different hardware.',
  'electric-motor':'Battery-electric and plug-in-hybrid BMW models. The BMW iX3 fifth-generation eDrive system is a documented integrated-drive example.',
  'power-electronics':'Battery-electric and plug-in-hybrid BMW models using controlled electric traction. Packaging and electrical ratings differ by generation.',
  'traction-battery':'BMW battery-electric cars such as the i3, i4 and iX, plus plug-in hybrids with a smaller, differently packaged traction battery.',
};
export const encyclopediaParts = groups.flatMap(group => group.rows.trim().split('\n').map(row => {
  const [id,name,summary,analogy,location,technical,symptoms,bmwFact] = row.split('|');
  const original = partCatalog.find(part => part.id === id);
  const source = primarySources[group.source];
  return {
    id,name,system:group.system,summary,analogy,location,technical,symptoms,bmwFact,
    zone:group.zone,usedIn:applications[id] || group.usedIn,lifespan:group.life,cost:group.cost,
    url:`/parts/${id}`,photo:existingPhotos.get(id) || null,
    imageStatus:existingPhotos.has(id) ? (id==='turbocharger' ? 'identified-bmw-photo' : 'generic-reference-photo') : 'educational-diagram',
    sources:[source,...(original?.sources || []).filter(item=>item.url!==source.url)],
    verification:'Educational component-family description. Exact fitment, price, lifespan and matching BMW photography require vehicle-specific verification.',
    related:[],
  };
}));
for (const part of encyclopediaParts) {
  const peers=encyclopediaParts.filter(other=>other.system===part.system&&other.id!==part.id);
  const position=encyclopediaParts.filter(other=>other.system===part.system).indexOf(part);
  part.related=[...peers.slice(position,position+3),...peers.slice(0,3)].slice(0,3).map(other=>other.id);
}

export const partsImageManifest = encyclopediaParts.map(part=>({
  id:part.id,name:part.name,page:part.url,status:part.id==='turbocharger'?'identified-bmw-reference-photo':part.photo?'reference-photo-needs-exact-fitment':'missing-exact-component-photo',
  currentSource:part.photo?.page || null,currentCredit:part.photo?.author || 'Original Motron educational diagram',
  currentLicense:part.photo?.license || 'Original educational artwork; no photograph implied',
  required:'Sharp, unmodified BMW component photograph with identified engine/chassis, source, author, license and accessible alt text.',
  suggestedSearch:`https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(`BMW ${part.name}`)}&title=Special:MediaSearch&type=image`,
}));
